#pragma once
#include <type_traits>
#include <jni/jni.h>
#include "../util/fixed_string.hpp"
#include "object.hpp"
#include "wrap.hpp"

#if defined(_MSC_VER)
#define JABA_NO_UNIQUE_ADDRESS [[msvc::no_unique_address]]
#else
#define JABA_NO_UNIQUE_ADDRESS [[no_unique_address]]
#endif

namespace jaba
{
	// Loc of a static member, there is no instance to find
	struct static_loc { };

	// Common base of field and method. Stateless, a member is an empty object living inside a
	// members struct, Loc::owner(const void* member) (generated by JABA_FIELD) walks back from
	// the member's address to the instance it lives in.
	template <class ClassT, fixed_string Mapping, class Loc>
	class clazz_member : public mapped<Mapping>
	{
	public:
		static constexpr bool is_static = std::is_same_v<Loc, static_loc>;

		using mapped<Mapping>::mapping;

	protected:
		// the class the member is looked up on
		[[nodiscard]] static jclass cls()
		{
			return ClassT::native();
		}

		// the instance the member belongs to, member is the address of the derived field/method
		[[nodiscard]] static jobject self(const void* const member) noexcept
		{
			return Loc::owner(member).obj();
		}
	};

	namespace detail
	{
		// raw jni value -> ValT (clazz types get wrapped in an object)
		template <class V, class R>
		[[nodiscard]] V wrap(const R raw)
		{
			if constexpr (std::is_same_v<V, R>)
				return raw;
			else
			{
				static_assert(std::is_constructible_v<V, jobject>, "add 'using clazz::clazz;' to this class");
				return V{ raw };
			}
		}

		// ValT -> raw jni value
		template <class V>
		[[nodiscard]] auto unwrap(const V& val) noexcept
		{
			if constexpr (std::is_arithmetic_v<V>)
				return val;
			else
				return val.obj();
		}
	}
}
